import{_ as i,W as o,s as d,u as r,ah as p,I as l,w as s,Z as e,A as t}from"./chunks/framework.DYeiaKBS.js";import"./chunks/theme.DJBbXXYU.js";const b=JSON.parse('{"title":"如何解决 “mount.nfs: Stale file handle”错误 | LCTT x X-CMD","titleTemplate":false,"description":"如何解决 “mount.nfs: Stale file handle”错误 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何解决 “mount.nfs: Stale file handle”错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何解决 “mount.nfs: Stale file handle”错误 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20170101 How to resolve mount.nfs- Stale file handle error","title":"如何解决 “mount.nfs: Stale file handle”错误","tag":"201804"},"relativePath":"201804/20170101 How to resolve mount.nfs- Stale file handle error.md","filePath":"[post].md"}'),u={name:"201804/20170101 How to resolve mount.nfs- Stale file handle error.md"};function f(m,n,g,S,h,c){const a=o("Link");return r(),d("div",null,[n[21]||(n[21]=p(`<h1 id="如何解决-mount-nfs-stale-file-handle-错误" tabindex="-1">如何解决 “mount.nfs: Stale file handle”错误 <a class="header-anchor" href="#如何解决-mount-nfs-stale-file-handle-错误" aria-label="Permalink to 如何解决 “mount.nfs: Stale file handle”错误">​</a></h1><blockquote><p>了解如何解决 Linux 平台上的 <code>mount.nfs: Stale file handle</code> 错误。这个 NFS 错误可以在客户端或者服务端解决。</p></blockquote><p><em><img src="http://kerneltalks.com/wp-content/uploads/2017/01/nfs_error-2-150x150.png" alt=""></em></p><p>当你在你的环境中使用网络文件系统时，你一定不时看到 <code>mount.nfs：Stale file handle</code> 错误。此错误表示 NFS 共享无法挂载，因为自上次配置后有些东西已经更改。</p><p>无论是你重启 NFS 服务器或某些 NFS 进程未在客户端或服务器上运行，或者共享未在服务器上正确输出，这些都可能是导致这个错误的原因。此外，当这个错误发生在先前挂载的 NFS 共享上时，它会令人不快。因为这意味着配置部分是正确的，因为是以前挂载的。在这种情况下，可以尝试下面的命令：</p><p>确保 NFS 服务在客户端和服务器上运行良好。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#  service nfs status</span></span>
<span class="line"><span>rpc.svcgssd is stopped</span></span>
<span class="line"><span>rpc.mountd (pid 11993) is running...</span></span>
<span class="line"><span>nfsd (pid 12009 12008 12007 12006 12005 12004 12003 12002) is running...</span></span>
<span class="line"><span>rpc.rquotad (pid 11988) is running...</span></span></code></pre></div><p>如果 NFS 共享目前挂载在客户端上，则强制卸载它并尝试在 NFS 客户端上重新挂载它。通过 <code>df</code> 命令检查它是否正确挂载，并更改其中的目录。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># umount -f /mydata_nfs</span></span>
<span class="line"><span> </span></span>
<span class="line"><span># mount -t nfs server:/nfs_share /mydata_nfs</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>#df -k</span></span>
<span class="line"><span>------ output clipped -----</span></span>
<span class="line"><span>server:/nfs_share 41943040  892928  41050112   3% /mydata_nfs</span></span></code></pre></div>`,9)),l("p",null,[n[1]||(n[1]=s("在上面的挂载命令中，服务器可以是 NFS 服务器的 IP 或")),e(a,{href:"https://kerneltalks.com/linux/all-you-need-to-know-about-hostname-in-linux/"},{default:t(()=>n[0]||(n[0]=[s("主机名")])),_:1}),n[2]||(n[2]=s("。"))]),n[22]||(n[22]=p(`<p>如果你在强制取消挂载时遇到像下面错误：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># umount -f /mydata_nfs</span></span>
<span class="line"><span>umount2: Device or resource busy</span></span>
<span class="line"><span>umount: /mydata_nfs: device is busy</span></span>
<span class="line"><span>umount2: Device or resource busy</span></span>
<span class="line"><span>umount: /mydata_nfs: device is busy</span></span></code></pre></div><p>然后你可以用 <code>lsof</code> 命令来检查哪个进程或用户正在使用该挂载点，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># lsof |grep mydata_nfs</span></span>
<span class="line"><span>lsof: WARNING: can&#39;t stat() nfs file system /mydata_nfs</span></span>
<span class="line"><span>      Output information may be incomplete.</span></span>
<span class="line"><span>su         3327      root  cwd   unknown                                                   /mydata_nfs/dir (stat: Stale NFS file handle)</span></span>
<span class="line"><span>bash       3484      grid  cwd   unknown                                                   /mydata_nfs/MYDB (stat: Stale NFS file handle)</span></span>
<span class="line"><span>bash      20092  oracle11  cwd   unknown                                                   /mydata_nfs/MPRP (stat: Stale NFS file handle)</span></span>
<span class="line"><span>bash      25040  oracle11  cwd   unknown                                                   /mydata_nfs/MUYR (stat: Stale NFS file handle)</span></span></code></pre></div><p>如果你在上面的示例中看到共有 4 个 PID 正在使用该挂载点上的某些文件。尝试杀死它们以释放挂载点。完成后，你将能够正确卸载它。</p><p>有时 <code>mount</code> 命令会有相同的错误。接着使用下面的命令在客户端重启 NFS 服务后挂载。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#  service nfs restart</span></span>
<span class="line"><span>Shutting down NFS daemon:                                  [  OK  ]</span></span>
<span class="line"><span>Shutting down NFS mountd:                                  [  OK  ]</span></span>
<span class="line"><span>Shutting down NFS quotas:                                  [  OK  ]</span></span>
<span class="line"><span>Shutting down RPC idmapd:                                  [  OK  ]</span></span>
<span class="line"><span>Starting NFS services:                                     [  OK  ]</span></span>
<span class="line"><span>Starting NFS quotas:                                       [  OK  ]</span></span>
<span class="line"><span>Starting NFS mountd:                                       [  OK  ]</span></span>
<span class="line"><span>Starting NFS daemon:                                       [  OK  ]</span></span></code></pre></div>`,7)),l("p",null,[n[4]||(n[4]=s("另请阅读：")),e(a,{href:"http://kerneltalks.com/hpux/restart-nfs-in-hpux/"},{default:t(()=>n[3]||(n[3]=[s("如何在 HPUX 中逐步重启 NFS")])),_:1})]),l("p",null,[n[6]||(n[6]=s("即使这没有解决你的问题，最后一步是在 NFS 服务器上重启服务。警告！这将断开从该 NFS 服务器输出的所有 NFS 共享。所有客户端将看到挂载点断开。这一步将 99％ 解决你的问题。如果没有，请务必检查 ")),e(a,{href:"http://kerneltalks.com/linux/nfs-configuration-linux-hpux/"},{default:t(()=>n[5]||(n[5]=[s("NFS 配置")])),_:1}),n[7]||(n[7]=s("，提供你修改的配置并发布你启动时看到的错误。"))]),n[23]||(n[23]=l("p",null,"上面文章中的输出来自 RHEL6.3 服务器。请将你的评论发送给我们。",-1)),n[24]||(n[24]=l("hr",null,null,-1)),l("p",null,[n[9]||(n[9]=s("via: ")),e(a,{href:"https://kerneltalks.com/troubleshooting/resolve-mount-nfs-stale-file-handle-error/"},{default:t(()=>n[8]||(n[8]=[s("https://kerneltalks.com/troubleshooting/resolve-mount-nfs-stale-file-handle-error/")])),_:1})]),l("p",null,[n[13]||(n[13]=s("作者：")),e(a,{href:"https://kerneltalks.com"},{default:t(()=>n[10]||(n[10]=[s("KernelTalks")])),_:1}),n[14]||(n[14]=s(" 译者：")),e(a,{href:"https://github.com/geekpi"},{default:t(()=>n[11]||(n[11]=[s("geekpi")])),_:1}),n[15]||(n[15]=s(" 校对：")),e(a,{href:"https://github.com/wxy"},{default:t(()=>n[12]||(n[12]=[s("wxy")])),_:1})]),l("p",null,[n[18]||(n[18]=s("本文由 ")),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>n[16]||(n[16]=[s("LCTT")])),_:1}),n[19]||(n[19]=s(" 原创编译，")),e(a,{href:"https://linux.cn/"},{default:t(()=>n[17]||(n[17]=[s("Linux中国")])),_:1}),n[20]||(n[20]=s(" 荣誉推出"))])])}const N=i(u,[["render",f]]);export{b as __pageData,N as default};
